package main

import (
	"context"
	"errors"
	"fmt"
)

func main() {
	ctx, cancel := context.WithCancelCause(context.Background())
	cancel(errors.New("x"))
	if context.Cause(ctx).Error() == "x" {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
}

