	"time"
)

func main() {
	early := time.Now().Add(-time.Second)
	parent, c1 := context.WithDeadline(context.Background(), early)
	defer c1()
	later := time.Now().Add(time.Hour)
	child, c2 := context.WithDeadline(parent, later)
	defer c2()
	if child.Err() == context.DeadlineExceeded {
		fmt.Println(1)
	} else {
		fmt.Println(0)
	}
}

