import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
)

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	cancel()
	var n atomic.Int32
	var wg sync.WaitGroup
	wg.Add(2)
	context.AfterFunc(ctx, func() {
		n.Add(1)
		wg.Done()
	})
	context.AfterFunc(ctx, func() {
		n.Add(1)
		wg.Done()
	})
	wg.Wait()
	fmt.Println(n.Load())
}

